"use strict";var nickName;$(document).ready(function(){$("#Employee").autocomplete({source:function(n,t){var i=n.term,r=i.indexOf(" (");r>0&&(i=i.substr(0,r));$.ajax({url:_global.root+"employee/GetEmployees",dataType:"json",data:{query:i,isSpecial:!1},success:function(n){n.Employees&&n.Employees.length>0?t($.map(n.Employees,function(n){return{label:n.NickName+" ("+n.FullName+")",value:n.Id}})):$("#EmployeeId").val("0")}})},delay:500,minLength:1,select:function(n,t){nickName=t.item.label;$("#Employee").val(nickName);$("#EmployeeId").val(t.item.value);var i=parseInt($("#EmployeeId").val());i>0&&$.getJSON(_global.root+"request/GetUnavailDate",{employeeId:i},function(n){if(n!=null){var t=parseInt($("#ForRequest").val());switch(t){case 0:$("#FromDate, #ToDate").attr("disableddate",n.join(","));$("#FromDate, #ToDate").change();break;case 1:$("#ForDate").attr("disabledDate",n.join(","));$("#ForDate").change();shiftChange();break;case 2:$("#ForDate").change()}initDatePicker()}})},focus:function(n,t){$("#Employee").val(t.item.label);n.preventDefault()},close:function(){nickName?$("#Employee").val(nickName):$("#Employee").val(_global.nickName)}})});$(document).ready(function(){var n=$("#successed").val();n==="true"&&confirm('<i class="icon-success mdi mdi-checkbox-marked-circle-outline"><\/i><p>Successfull!<\/p><p>Press OK to continue<\/p>',function(){document.location=_global.root+"lateearly/index"});$("#Employee").val(_global.nickName);$("#EmployeeId").val(_global.employeeId)});